app.MapPost("/api/payments", async (PaymentRequest req, IPaymentService svc) =>
{
    if (req.Amount <= 0)
        return Results.ValidationProblem(new Dictionary<string, string[]>
        {
            ["amount"] = ["Amount must be positive."]
        }); // 400

    var result = await svc.ChargeAsync(req);
    return result switch
    {
        PaymentOutcome.Success s => Results.Created($"/api/payments/{s.Id}", s),
        PaymentOutcome.Duplicate => Results.Conflict(new { error = "Duplicate idempotency key." }),
        PaymentOutcome.Declined d => Results.UnprocessableEntity(new { error = d.Reason }),
        _ => Results.StatusCode(502) // upstream gateway failure
    };
});

record PaymentRequest(decimal Amount, string IdempotencyKey);

[HttpPut("{id:guid}")]
[ProducesResponseType(typeof(ProductDto), StatusCodes.Status200OK)]
[ProducesResponseType(StatusCodes.Status404NotFound)]
[ProducesResponseType(StatusCodes.Status409Conflict)]
public async Task<ActionResult<ProductDto>> Replace(
    Guid id, ProductDto dto, CancellationToken ct)
{
    var existing = await repo.GetAsync(id, ct);
    if (existing is null) return NotFound();

    if (existing.RowVersion != dto.RowVersion)
        return Conflict("Row was modified by another user.");

    await repo.ReplaceAsync(dto, ct);
    return Ok(dto);
}

